fix.code:
while (running) {
    ConsumerRecords<String, Notification> records = consumer.poll(Duration.ofMillis(500));
    Map<TopicPartition, OffsetAndMetadata> toCommit = new HashMap<>();
    for (ConsumerRecord<String, Notification> record : records) {
        emailSender.send(record.value(), record.value().notificationId());   // id duy nhất của message làm idempotency key
        toCommit.put(new TopicPartition(record.topic(), record.partition()),
                     new OffsetAndMetadata(record.offset() + 1));
    }
    if (!toCommit.isEmpty()) {
        consumer.commitSync(toCommit);   // một lần mỗi lô thay vì mỗi record
    }
}

// Hoặc dùng Spring Kafka: @KafkaListener với AckMode.BATCH hoặc RECORD,
// container tự commit đúng offset + 1.
